'use strict';
P.Game={
start(){const chosen=P.state.chosen;Object.assign(P.state,{mode:'play',player:P.Entities.player(P.Data.characters[chosen]),enemies:[],shots:[],danger:[],gems:[],effects:[],elapsed:0,spawn:0,fire:0,kills:0,level:1,xp:0,need:6,bossSpawned:false});P.Core.clear();document.body.classList.remove('menu');P.$('#menu').hidden=true;P.$('#overlay').hidden=true;P.$('#hud').hidden=false;P.$('#pause').hidden=false;P.$('#hint').textContent='PLAZA DEL CAUSAS · RECOGE FAMA Y ELIGE MEJORAS';P.UI.hud()},
update(dt){const s=P.state;if(s.mode!=='play')return;s.elapsed+=dt;P.Systems.spawn(dt);P.Systems.move(dt);if(s.mode!=='play')return;P.Combat.tick(dt);if(s.mode!=='play')return;P.Systems.collect(dt);P.UI.hud()},
finish(win){const s=P.state;s.mode='end';P.Save.write(s.kills);P.UI.hud();P.UI.show(win?'¡La plaza es tuya!':'Se cayó el directo.',(win?'Derrotaste a ElZeein':'Una racha más, causa')+' · '+P.Core.clock(s.elapsed)+' · '+s.kills+' trolls · Nivel '+s.level,[{title:'Otra partida ↗',action:()=>this.start()},{title:'Elegir otro causa',action:()=>P.UI.menu()}])},
boot(){P.UI.init();P.Sprites.init();let last=0;const frame=time=>{const dt=Math.min((time-last)/1000,.04);last=time;this.update(dt);P.World.render(time);P.UI.animate(time);requestAnimationFrame(frame)};requestAnimationFrame(frame)}
};P.Game.boot();